#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v;
    double w;
    bool operator<(const Edge &o) const {
        return w > o.w;
    }
};

struct DSU {
    vector<int> parent, rank;
    DSU(int n) {
        parent.resize(n);
        rank.resize(n, 0);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return false;
        if (rank[rx] < rank[ry]) swap(rx, ry);
        parent[ry] = rx;
        if (rank[rx] == rank[ry]) rank[rx]++;
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> x(N), y(N), w(N);
    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i] >> w[i];
    }

    vector<Edge> edges;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            double dist = sqrt((double)(x[i] - x[j]) * (x[i] - x[j]) + 
                               (double)(y[i] - y[j]) * (y[i] - y[j]));
            double edgeWeight = (w[i] + w[j]) / dist; // max water that can pass
            edges.push_back({i, j, edgeWeight});
        }
    }

    sort(edges.begin(), edges.end());

    DSU dsu(N);
    double answer = 1e18;
    for (auto &e : edges) {
        if (dsu.unite(e.u, e.v)) {
            answer = min(answer, e.w);
        }
    }

    cout << fixed << setprecision(6) << answer << "\n";
    return 0;
}

