#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<double> x(N), y(N), w(N);
    for (int i = 0; i < N; i++) cin >> x[i] >> y[i] >> w[i];

    const double INF = 1e100;

    // gain[i][j] = fraction of water remaining when moved from i to j
    // The original problem's leakage depends on Euclidean distance:
    // remaining fraction = 2^{-dist}
    vector<vector<double>> gain(N, vector<double>(N, 0.0));
    for (int i = 0; i < N; i++) {
        gain[i][i] = 1.0;
        for (int j = 0; j < N; j++) {
            double dx = x[i] - x[j];
            double dy = y[i] - y[j];
            double d = sqrt(dx * dx + dy * dy);
            gain[i][j] = pow(0.5, d);
        }
    }

    // Floyd-Warshall on multiplicative weights:
    // best[i][j] = maximum remaining fraction achievable from i to j
    vector<vector<double>> best = gain;
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            if (best[i][k] == 0.0) continue;
            for (int j = 0; j < N; j++) {
                best[i][j] = max(best[i][j], best[i][k] * best[k][j]);
            }
        }
    }

    auto feasible = [&](double m) -> bool {
        // Need every city to end with at least m.
        // Let surplus at i be max(0, w[i]-m), deficit at j be max(0, m-w[j]).
        // Since water is perfectly divisible and transfer losses are linear,
        // total deliverable water to deficits is:
        // sum_i surplus_i * best[i][j].
        //
        // A standard necessary and sufficient condition here is:
        // total available "effective" water can satisfy all deficits.
        // We model it as a max-flow on surplus/deficit bipartite graph.
        int S = 0;
        int offsetL = 1;
        int offsetR = offsetL + N;
        int T = offsetR + N;
        int V = T + 1;

        struct Edge {
            int to, rev;
            double cap;
        };
        vector<vector<Edge>> g(V);

        auto add_edge = [&](int fr, int to, double cap) {
            g[fr].push_back({to, (int)g[to].size(), cap});
            g[to].push_back({fr, (int)g[fr].size() - 1, 0.0});
        };

        double totalDef = 0.0;
        for (int i = 0; i < N; i++) {
            double s = max(0.0, w[i] - m);
            if (s > 0) add_edge(S, offsetL + i, s);
        }
        for (int j = 0; j < N; j++) {
            double d = max(0.0, m - w[j]);
            if (d > 0) {
                add_edge(offsetR + j, T, d);
                totalDef += d;
            }
        }

        for (int i = 0; i < N; i++) {
            double s = max(0.0, w[i] - m);
            if (s <= 0) continue;
            for (int j = 0; j < N; j++) {
                double d = max(0.0, m - w[j]);
                if (d <= 0) continue;
                double deliver = s * best[i][j];
                if (deliver > 0) add_edge(offsetL + i, offsetR + j, deliver);
            }
        }

        double flow = 0.0;
        const double EPS = 1e-10;

        while (true) {
            vector<int> level(V, -1);
            queue<int> q;
            level[S] = 0;
            q.push(S);
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                for (auto &e : g[v]) {
                    if (e.cap > EPS && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.push(e.to);
                    }
                }
            }
            if (level[T] < 0) break;

            vector<int> it(V, 0);
            function<double(int, double)> dfs = [&](int v, double f) -> double {
                if (v == T) return f;
                for (int &i = it[v]; i < (int)g[v].size(); i++) {
                    Edge &e = g[v][i];
                    if (e.cap <= EPS || level[v] >= level[e.to]) continue;
                    double ret = dfs(e.to, min(f, e.cap));
                    if (ret > EPS) {
                        e.cap -= ret;
                        g[e.to][e.rev].cap += ret;
                        return ret;
                    }
                }
                return 0.0;
            };

            while (true) {
                double f = dfs(S, INF);
                if (f <= EPS) break;
                flow += f;
            }
        }

        return flow + 1e-8 >= totalDef;
    };

    double lo = 0.0, hi = 0.0;
    for (double v : w) hi = max(hi, v);
    // Upper bound can never exceed average without loss, but max(w) is enough.

    for (int iter = 0; iter < 80; iter++) {
        double mid = (lo + hi) / 2.0;
        if (feasible(mid)) lo = mid;
        else hi = mid;
    }

    cout << fixed << setprecision(10) << lo << '\n';
    return 0;
}

