#define MAXN 100

int n;
double a[MAXN];
double x[MAXN], y[MAXN];
int adj[MAXN][MAXN];
int visited[MAXN];

double dist(int i, int j) {
    double dx = x[i] - x[j];
    double dy = y[i] - y[j];
    return sqrt(dx*dx + dy*dy);
}

void dfs(int u, int n) {
    visited[u] = 1;
    for (int v = 0; v < n; v++) {
        if (adj[u][v] && !visited[v]) {
            dfs(v, n);
        }
    }
}

int can(double target) {
    memset(adj, 0, sizeof(adj));
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            if (a[i] + a[j] - dist(i,j) >= 2.0 * target - 1e-9) {
                adj[i][j] = adj[j][i] = 1;
            }
        }
    }
    memset(visited, 0, sizeof(visited));
    dfs(0, n);
    for (int i = 0; i < n; i++) {
        if (!visited[i]) return 0;
    }
    return 1;
}

int main() {
