    double lo = 1e18, hi = -1e18;
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf %lf", &x[i], &y[i], &a[i]);
        if (a[i] < lo) lo = a[i];
        if (a[i] > hi) hi = a[i];
    }

    for (int iter = 0; iter < 100; iter++) {
