typedef long double ld;

typedef struct {
    ld x, y, w;
} City;

static int N;
static City *a;
static ld *sumReach;
static int *vis;
static int curMark;
static ld X;
static ld EPS = 1e-12L;

static ld dist2(int i, int j) {
    ld dx = a[i].x - a[j].x;
    ld dy = a[i].y - a[j].y;
    return dx * dx + dy * dy;
}

/*
Assumption of transfer rule (standard for this problem):
If city i sends water to city j at distance d, then after transfer
the amount arriving is sent_amount / 2^d.
Equivalently, to make 1 unit arrive at j from i, city i must spend 2^d units.

For a target minimum X:
A city with w[i] > X has surplus s[i] = w[i] - X.
A city with w[i] < X has deficit t[i] = X - w[i].

Water can be relayed through arbitrary cities. Since multiplying costs along a path
gives 2^(sum distances), the best route between two cities is any shortest-path route
under Euclidean edge lengths; but because all pairwise direct moves are allowed and
Euclidean distance satisfies triangle inequality, direct transfer is optimal.
Hence i can effectively contribute to j at efficiency factor 2^(-dist(i,j)).

A standard cut/closure observation for this complete metric with arbitrary relays:
Feasibility of X is equivalent to:
for every city j, total water that can be gathered at j from all cities with surplus,
plus its own initial water if below X, is enough to make it reach X.
This becomes:
sum_i max(0, w[i]-X) / 2^{dist(i,j)} >= max(0, X-w[j]) for all j.
This is sufficient because deficits can be satisfied independently via splitting flow,
and relays do not improve over direct transfer.

We binary search X.
*/

static int feasible(ld x) {
    for (int j = 0; j < N; j++) {
        ld need = x - a[j].w;
        if (need <= 0) continue;
        ld got = 0.0L;
        for (int i = 0; i < N; i++) {
            ld surplus = a[i].w - x;
            if (surplus <= 0) continue;
            ld d = sqrtl(dist2(i, j));
            got += surplus / powl(2.0L, d);
            if (got + EPS >= need) break;
        }
        if (got + EPS < need) return 0;
    }
    return 1;
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;
    a = (City*)malloc(sizeof(City) * N);
    for (int i = 0; i < N; i++) {
        double x, y, w;
        scanf("%lf %lf %lf", &x, &y, &w);
        a[i].x = (ld)x;
        a[i].y = (ld)y;
        a[i].w = (ld)w;
    }

    ld lo = 0.0L, hi = 0.0L;
    for (int i = 0; i < N; i++) hi += a[i].w;
    if (N > 0) hi /= N; /* cannot exceed average without losses */

    for (int it = 0; it < 100; it++) {
        ld mid = (lo + hi) / 2.0L;
        if (feasible(mid)) lo = mid;
        else hi = mid;
    }

    printf("%.15Lf\n", lo);

    free(a);
    return 0;
}

