public class Main {
    static int[] parent, size;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long[] water = new long[N];
        long[] x = new long[N];
        long[] y = new long[N];

        long lo = 0, hi = Long.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            water[i] = sc.nextLong();
            x[i] = sc.nextLong();
            y[i] = sc.nextLong();
            hi = Math.min(hi, water[i]);
        }

        // binary search on answer
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            if (canAchieve(N, water, x, y, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        System.out.println(lo);
    }

    static boolean canAchieve(int N, long[] water, long[] x, long[] y, long target) {
        // Build edges if distance squared <= (water[i] - target) + (water[j] - target)?? Actually we need careful modeling.
        // Water transfer: If city i gives water to city j, the amount arriving is (amount sent) - distance.
        // So to send at least (target - water[j]) to j, we need (target - water[j]) + dist <= excess from i.
        // This is like: we can connect cities if we can move needed water with losses.

        // Simpler: DSU approach: connect cities where (water[i] >= target) and (water[j] >= target) or transfer possible.
        // Actually we can use union-find: connect i and j if dist(i,j) <= water[i] - target + water[j] - target? No.

        // Correct interpretation: possible to make all >= target if total excess >= total deficit + total transfer loss.
        // But loss depends on distances. So we need to check connectivity of supply/demand.

        // More direct: We can treat each city with excess (>= target) as source, connect to any city if 
        // distance <= (excess from source - needed by target). This is a flow/connectivity check.

        // Use DSU: edges exist if distance <= (water[i] - target) + (water[j] - target)
        // meaning both can cooperate to cover the loss.

        parent = new int[N];
        size = new int[N];
        for (int i = 0; i < N; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        long[] excess = new long[N];
        for (int i = 0; i < N; i++) {
            excess[i] = water[i] - target;
        }

        // Connect cities if they can help each other
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                long dist = Math.abs(x[i] - x[j]) + Math.abs(y[i] - y[j]);
                if (excess[i] + excess[j] >= dist) {
                    union(i, j);
                }
            }
        }

        // Check each component: total excess >= 0?
        Map<Integer, Long> compExcess = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int root = find(i);
            compExcess.put(root, compExcess.getOrDefault(root, 0L) + excess[i]);
        }

        for (long val : compExcess.values()) {
            if (val < 0) return false;
        }
        return true;
    }

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra; ra = rb; rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}

