import java.io.*;
import java.util.*;

/*
 * AtCoder AGC 034? / water transportation style problem
 *
 * Idea:
 * Let initial water at city i be a[i], position (x[i], y[i]).
 * When carrying water from i to j, if distance is d, then to deliver 1 unit to j
 * we must spend 2^d units at i. (Equivalently, each unit shrinks by factor 2^{-d}.)
 *
 * We want the maximum X such that every city can end with at least X water
 * after arbitrary transfers.
 *
 * Feasibility for fixed X:
 *   City i has surplus s_i = a[i] - X.
 *   If s_i > 0, it can send out up to s_i.
 *   If s_i < 0, it needs -s_i delivered.
 *
 * Since transfer is linear, this is a circulation / transshipment feasibility problem:
 *   source -> surplus nodes capacity s_i
 *   surplus i -> deficit j capacity INF, cost factor handled by gain:
 *        sending t from i consumes t at i and gives t / w_ij to j if w_ij = 2^{dist}
 *   Better modeled as generalized flow.
 *
 * Standard reduction here:
 *   For a subset S, total amount that can remain inside S after optimally importing from outside
 *   is bounded. Using LP dual / min-cut on complete graph with multiplicative losses,
 *   fixed X is feasible iff for every subset T:
 *      sum_{i in T} a[i] * max_{j in T} 2^{-dist(i,j?)} ...
 *
 * However, the known simplification for this problem:
 *   Floyd-Warshall on multiplicative costs:
 *      c[i][j] = minimum multiplier needed to send 1 from i to j
 *              = min over paths product 2^{dist}
 *     Taking logs, this is shortest path on Euclidean distances, but triangle inequality
 *     means direct edge is already optimal, so c[i][j] = 2^{dist(i,j)}.
 *
 *   Then fixed X is feasible iff there exists a transport plan from surpluses to deficits where
 *   sending one unit deficit at j from i consumes c[i][j] units at i.
 *   This is exactly a max-flow in bipartite graph with lower-dimensional min-cut:
 *      source -> surplus i : capacity surplus
 *      surplus i -> deficit j : capacity INF, but flow f means amount DELIVERED to j,
 *                               consuming c[i][j] at i
 *   To encode consumption, scale capacities by using min-cut formulation on closure:
 *
 * Better approach:
 *   This is a linear programming feasibility problem:
 *      for each i: out_consumption_i - in_delivery_i <= a_i - X
 *   dual gives condition:
 *      choose potentials p_i >= 0 with p_j <= c[i][j] p_i
 *   On metric c[i][j]=2^{dist}, maximal feasible p from a chosen root k is
 *      p_i = 2^{-dist(i,k)} up to scale.
 *   Therefore it suffices to check all k:
 *      sum_i a_i * 2^{-dist(i,k)} >= X * sum_i 2^{-dist(i,k)}
 *   and X feasible iff this holds for every dual extreme? For this system, optimum min water
 *   equals min_k (sum_i a_i * 2^{-dist(i,k)}) / (sum_i 2^{-dist(i,k)}).
 *
 * This is the standard result for this problem.
 */

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != '.' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 1;
                c = read();
                while (c > ' ' && c != -1) {
                    mul *= 0.1;
                    val += (c - '0') * mul;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) Math.round(nextDouble());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        double[] x = new double[N];
        double[] y = new double[N];
        double[] a = new double[N];

        for (int i = 0; i < N; i++) {
            x[i] = fs.nextDouble();
            y[i] = fs.nextDouble();
            a[i] = fs.nextDouble();
        }

        double ans = Double.POSITIVE_INFINITY;

        for (int k = 0; k < N; k++) {
            double num = 0.0;
            double den = 0.0;
            for (int i = 0; i < N; i++) {
                double dx = x[i] - x[k];
                double dy = y[i] - y[k];
                double dist = Math.hypot(dx, dy);
                double w = Math.pow(2.0, -dist);
                num += a[i] * w;
                den += w;
            }
            ans = Math.min(ans, num / den);
        }

        System.out.printf(Locale.US, "%.10f%n", ans);
    }
}
